SOURCE_CLAIM_JSON: {"title":"As unrest grows, Iran restricts access to Instagram, WhatsApp","publisher":"Reuters (via Investing.com)","publication_date":"2022-09-21","url":"https://www.investing.com/news/world-news/as-unrest-grows-iran-restricts-access-to-instagram-whatsapp-2896618","claim":"Iran curbed access to Instagram and WhatsApp amid protests over Mahsa Amini's death; Reuters also reported NetBlocks data showing a nation-scale loss of connectivity and near-total disruption in parts of Kurdistan province.","locator":"L433-L443","source_type":"media","source_confidence":"high","source_confidence_reason":"Contemporaneous Reuters wire with direct technical corroboration from NetBlocks and multiple local-resident reports.","final_evidence_use":"final_evidence","period_fit":"Directly within the September 2022 protest crackdown.","ruler_attribution":"Attributed to Iranian authorities; Khamenei attribution is structural through his supreme authority over the security apparatus, not a direct order shown in this article.","contrary_evidence":["Iran's minister of communications said earlier on Wednesday he had been misquoted after news outlets cited him as saying the authorities might disrupt internet services for security reasons."],"lenses":["4B.6","4B.9"]}
SOURCE_CLAIM_JSON: {"title":"Treasury Sanctions Iranian Leaders Responsible for Internet Shutdown and Violent Crackdown on Peaceful Protests","publisher":"U.S. Department of the Treasury","publication_date":"2022-10-06","url":"https://home.treasury.gov/news/press-releases/jy0994","claim":"OFAC designated seven senior leaders in Iran's government and security apparatus for shutting down internet access and continuing violence against peaceful protesters after Mahsa Amini's death; the release also named the communications minister and cyber-police chief as responsible for blocking Internet access and monitoring users.","locator":"L604-L615 and L617-L623","source_type":"official","source_confidence":"high","source_confidence_reason":"Primary sanctions action naming officials and describing the conduct they were designated for.","final_evidence_use":"final_evidence","period_fit":"Immediate 2022 protest-period conduct.","ruler_attribution":"The press release attributes conduct to senior state/security officials, not personally to Khamenei, but the conduct falls within his structural command over the security state.","contrary_evidence":["The document is a sanctions finding, not a court judgment, and it does not prove a personal Khamenei order."],"lenses":["4B.6","4B.9"]}
SOURCE_CLAIM_JSON: {"title":"Iranian security forces step up arrests of journalists amid anti-state protests","publisher":"Committee to Protect Journalists","publication_date":"2022-09-29","url":"https://cpj.org/2022/09/iranian-security-forces-step-up-arrests-of-journalists-as-anti-state-protests-spread/","claim":"CPJ said at least 28 journalists had been arrested as clashes between security forces and protesters left dozens dead, with arrests taking place amid an internet blackout and major disruptions to phone and social media networks.","locator":"L518-L523","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Leading press-freedom NGO using multiple in-country sources and contemporaneous reporting; claim is specific and time-bounded.","final_evidence_use":"final_evidence","period_fit":"Directly within the September 2022 protest wave.","ruler_attribution":"Attributed to Iranian security forces; Khamenei attribution is indirect through supreme-leader control of the coercive apparatus.","contrary_evidence":["CPJ's count depends on in-country sources and media reports because access was constrained by the blackout."],"lenses":["4B.3","4B.6","4B.9"]}
